import sys
import math

def solve():
    input = sys.stdin.read
    data = input().split()
    iterator = iter(data)

    n = int(next(iterator))
    m = int(next(iterator))

    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    attacked = []
    for _ in range(m):
        attacked.append(int(next(iterator)))

    def bfs(start):
        dist = [-1] * (n + 1)
        dist[start] = 0
        queue = [start]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return dist

    max_dist = 0
    for city in attacked:
        d = bfs(city)
        for a in attacked:
            if d[a] > max_dist:
                max_dist = d[a]

    best_start = -1
    min_time = float('inf')

    for start in range(1, n + 1):
        dist = bfs(start)
        current_max = 0
        for a in attacked:
            current_max = max(current_max, dist[a])

        if current_max < min_time:
            min_time = current_max
            best_start = start
        elif current_max == min_time:
            if start < best_start:
                best_start = start

    print(best_start)
    print(min_time)

if __name__ == '__main__':
    solve()
